var userConnection = this.Get<UserConnection>("UserConnection");
var spec = Get<Guid>("BPOwner");
var projId = Get<Guid>("BPProjectId");
var taskNumber = Get<String>("BPTaskNumber");
var taskName = Get<String>("BPTaskName");
var MessageBody = JsonConvert.SerializeObject(new { Id = spec.ToString(), ProjectId = projId, TaskNumber = taskNumber, TaskName = taskName });
BPMSoft.Configuration.MsgChannelUtilities.PostMessage(userConnection, "TaskOnTheGo", MessageBody);
return true;
